#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RituelKeyword {
    Reveil, Sommeil, Chaos, Harmonie,
    Attraction, Repulsion, Aurore, Reparation,
}

impl RituelKeyword {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "RÉVEIL"     => Some(Self::Reveil),
            "SOMMEIL"    => Some(Self::Sommeil),
            "CHAOS"      => Some(Self::Chaos),
            "HARMONIE"   => Some(Self::Harmonie),
            "ATTRACTION" => Some(Self::Attraction),
            "RÉPULSION"  => Some(Self::Repulsion),
            "AURORE"     => Some(Self::Aurore),
            "RÉPARATION" => Some(Self::Reparation),
            _            => None,
        }
    }
}
